/**
 * Step 3 — Offers. Manages the list of offers for this service.
 *
 * The page-level state holds an array of `OfferDraft` objects. This component:
 *   - shows the offer form when there are no offers yet (or the user clicked "Add")
 *   - shows the list of saved offer cards otherwise
 *   - Each card can be expanded (offer-detail editor inline) or opened in the
 *     theme editor via the 3-dot menu.
 *
 * The actual inline theme editor is a sibling component (OfferThemeEditor)
 * mounted by the parent — this step just emits the request via `onEditTheme`.
 */

'use client';

import { useState } from 'react';
import Box from '@mui/material/Box';
import Typography from '@mui/material/Typography';
import { MoreHorizontal, Copy, Trash2, Tag, Plus, Paintbrush } from 'lucide-react';

import {
  Card, Button, Input, Select, Switch, StatusPill, Menu, useMenu, IconButton, Banner,
} from '../';

export interface OfferDraft {
  id:        string;
  name:      string;
  type:      string;
  firewall:  string;
  online:    boolean;
  themed:    boolean;
}

export interface Step3OffersProps {
  offers:        OfferDraft[];
  onAddOffer:    (offer: OfferDraft) => void;
  onUpdateOffer: (id: string, patch: Partial<OfferDraft>) => void;
  onRemoveOffer: (id: string) => void;
  onEditTheme:   (id: string) => void;
}

const TYPE_OPTIONS     = ['Subscription', 'One-off', 'CPA', 'CPA-Sub'];
const FIREWALL_OPTIONS = ['Tier 1', 'Tier 2', 'No firewall'];

export function Step3Offers({ offers, onAddOffer, onUpdateOffer, onRemoveOffer, onEditTheme }: Step3OffersProps) {
  const [creating, setCreating] = useState(offers.length === 0);

  if (creating || offers.length === 0) {
    return (
      <OfferForm
        onSave={(o) => { onAddOffer(o); setCreating(false); }}
        onCancel={offers.length > 0 ? () => setCreating(false) : undefined}
      />
    );
  }

  return (
    <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
      <Box sx={{ display: 'flex', alignItems: 'flex-end', justifyContent: 'space-between', gap: 1 }}>
        <Box>
          <Typography component="h2" sx={{ fontSize: 16, fontWeight: 600, color: 'text.primary' }}>Offers</Typography>
          <Typography sx={{ fontSize: 13, color: 'text.secondary', mt: 0.25 }}>
            An offer is what the user subscribes to. Configure pricing and which operators it runs on.
          </Typography>
        </Box>
        <Button variant="secondary" leftIcon={<Plus size={14} />} onClick={() => setCreating(true)}>
          Add offer
        </Button>
      </Box>

      {offers.map((o, i) => (
        <OfferCard
          key={o.id}
          offer={o}
          idx={i + 1}
          onChangeOnline={(v) => onUpdateOffer(o.id, { online: v })}
          onEditTheme={() => onEditTheme(o.id)}
          onRemove={() => onRemoveOffer(o.id)}
        />
      ))}
    </Box>
  );
}

// ----- Offer creation form -----------------------------------------------
function OfferForm({ onSave, onCancel }: { onSave: (o: OfferDraft) => void; onCancel?: () => void }) {
  const [name, setName]         = useState('Weekly Premium');
  const [type, setType]         = useState('Subscription');
  const [firewall, setFirewall] = useState('');
  const [online, setOnline]     = useState(true);

  return (
    <Card>
      <Box sx={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', mb: 2 }}>
        <Box>
          <Typography component="h2" sx={{ fontSize: 16, fontWeight: 600, color: 'text.primary' }}>New offer</Typography>
          <Typography sx={{ fontSize: 13, color: 'text.secondary', mt: 0.25 }}>
            Configure the offer. Operator-level pricing and CAPs are set per country once you save.
          </Typography>
        </Box>
        {onCancel && (
          <IconButton onClick={onCancel} aria-label="Cancel"><Trash2 size={16} /></IconButton>
        )}
      </Box>

      <Banner tone="info">
        <strong>Default state — Draft.</strong>{' '}
        Status will be managed automatically during review and launch phases.
      </Banner>

      <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2.5, mt: 2.5 }}>
        <Input label="Offer name" value={name} onChange={(e) => setName((e.target as HTMLInputElement).value)} />
        <Select label="Offer type" options={TYPE_OPTIONS} value={type} onChange={(e) => setType(e.target.value as string)} />
        <Select label="Firewall ID" placeholder="Select firewall" options={FIREWALL_OPTIONS} value={firewall} onChange={(e) => setFirewall(e.target.value as string)} />
        <Switch label="Online" checked={online} onChange={(_e, v) => setOnline(v)} />
      </Box>

      <Box sx={{ display: 'flex', justifyContent: 'flex-end', gap: 1, mt: 3 }}>
        {onCancel && <Button variant="ghost" onClick={onCancel}>Cancel</Button>}
        <Button variant="primary" onClick={() => onSave({ id: `offer-${Date.now()}`, name, type, firewall, online, themed: false })}>
          Save offer
        </Button>
      </Box>
    </Card>
  );
}

// ----- Offer card (saved) -------------------------------------------------
function OfferCard({ offer, idx, onChangeOnline, onEditTheme, onRemove }: {
  offer: OfferDraft;
  idx:   number;
  onChangeOnline: (v: boolean) => void;
  onEditTheme:    () => void;
  onRemove:       () => void;
}) {
  const { anchor, open, openMenu, closeMenu } = useMenu();

  return (
    <Card padded={false}>
      <Box sx={{ display: 'flex', alignItems: 'center', gap: 1.5, paddingInline: 2, paddingBlock: 1.5 }}>
        {/* Tag avatar */}
        <Box sx={{ width: 36, height: 36, borderRadius: 1.5, backgroundColor: '#eff6ff', color: '#2563eb', display: 'grid', placeItems: 'center', flexShrink: 0 }}>
          <Tag size={16} />
        </Box>
        <Box sx={{ width: 8, height: 8, borderRadius: '50%', backgroundColor: offer.online ? '#10b981' : '#a1a1aa', boxShadow: '0 0 0 2px #fff', flexShrink: 0 }} />
        <Box sx={{ minWidth: 0, flex: 1, display: 'flex', alignItems: 'center', gap: 1, fontSize: 14 }}>
          <Box sx={{ fontWeight: 600, color: 'text.primary' }}>Offer-{idx}</Box>
          <Box sx={{ color: 'border.strong' }}>|</Box>
          <Box sx={{ color: 'text.secondary', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{offer.name}</Box>
          <Box sx={{ color: 'border.strong' }}>|</Box>
          <Box sx={{ color: 'text.secondary' }}>{offer.type}</Box>
        </Box>
        {offer.themed && (
          <Box sx={{ display: 'inline-flex', alignItems: 'center', height: 22, paddingInline: 1, borderRadius: 9999, backgroundColor: '#ede9fe', color: '#6d28d9' }} title="Has custom theme">
            <Paintbrush size={12} />
          </Box>
        )}
        <Switch checked={offer.online} onChange={(_e, v) => onChangeOnline(v)} />
        <IconButton onClick={openMenu} aria-label="More actions"><MoreHorizontal size={16} /></IconButton>
      </Box>

      <Menu anchorEl={anchor} open={open} onClose={closeMenu}>
        <Menu.Item icon={<Copy size={14} />}    onClick={() => { closeMenu(); onEditTheme(); }}>
          {offer.themed ? 'Edit theme' : 'Duplicate & edit theme'}
        </Menu.Item>
        <Menu.Divider />
        <Menu.Item icon={<Trash2 size={14} />} variant="danger" onClick={() => { closeMenu(); onRemove(); }}>
          Delete offer
        </Menu.Item>
      </Menu>
    </Card>
  );
}
