/**
 * OfferThemeEditor — Step 3 takeover for editing an offer's custom theme.
 *
 * Mounted INSIDE Step 3 by the wizard. When open it replaces Step 3's
 * content with a header banner ("Editing theme for Offer-1") + a compact
 * theme editor (phone preview + property panel). "I'm done" → confirmation
 * modal → on confirm, the parent marks the offer as themed.
 *
 * The parent owns "is the takeover open?" state and the target offer's id.
 */

'use client';

import { useState } from 'react';
import Box from '@mui/material/Box';
import Typography from '@mui/material/Typography';
import { Paintbrush, Check } from 'lucide-react';

import { Card, Input, Button, Dialog, Banner } from '../';

export interface OfferThemeEditorProps {
  offerLabel: string;
  /** Called when the user confirms "I'm done" (after the modal) */
  onDone:     () => void;
  /** Called when the user cancels or closes */
  onCancel:   () => void;
}

export function OfferThemeEditor({ offerLabel, onDone, onCancel }: OfferThemeEditorProps) {
  const [headline, setHeadline]               = useState('Enter your phone number');
  const [bgColor, setBgColor]                 = useState('#ffffff');
  const [btnColor, setBtnColor]               = useState('#18181b');
  const [headlineColor, setHeadlineColor]     = useState('#0f172a');
  const [logoBgColor, setLogoBgColor]         = useState('#7c3aed');
  const [showConfirm, setShowConfirm]         = useState(false);

  return (
    <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
      <Box>
        <Typography component="h2" sx={{ fontSize: 16, fontWeight: 600, color: 'text.primary' }}>
          Offer theme settings
        </Typography>
        <Typography sx={{ fontSize: 13, color: 'text.secondary', mt: 0.25 }}>
          Offer-specific theme override for {offerLabel}. Per-element styling is below.
        </Typography>
      </Box>

      <Card>
        <Box sx={{ display: 'grid', gridTemplateColumns: { xs: '1fr', md: '1fr 1.2fr' }, gap: 2.5 }}>
          {/* Phone preview */}
          <Box sx={{ backgroundColor: 'surface.muted', borderRadius: 1.5, p: 2, display: 'grid', placeItems: 'center' }}>
            <Box sx={{
              width: 180, borderRadius: 3, overflow: 'hidden',
              border: '6px solid #18181b',
              backgroundColor: '#fff',
              boxShadow: (t) => t.shadows[1],
            }}>
              <Box sx={{ height: 24, backgroundColor: '#18181b' }} />
              <Box sx={{ paddingInline: 1.5, paddingBlock: 2, display: 'flex', flexDirection: 'column', gap: 1.25, backgroundColor: bgColor, transition: 'background-color .2s' }}>
                <Box sx={{
                  width: 36, height: 36, borderRadius: '50%',
                  display: 'grid', placeItems: 'center',
                  backgroundColor: logoBgColor, color: '#fff',
                  fontSize: 12, fontWeight: 600, transition: 'background-color .2s',
                }}>
                  M
                </Box>
                <Box sx={{ fontSize: 12, fontWeight: 600, color: headlineColor, lineHeight: 1.2, transition: 'color .2s' }}>{headline}</Box>
                <Box sx={{ fontSize: 10, color: '#71717a', lineHeight: 1.2 }}>We'll send you a code by SMS to confirm.</Box>
                <Box sx={{ height: 28, borderRadius: 1, border: '1px solid #e4e4e7', backgroundColor: '#fff', paddingInline: 1, fontSize: 10, color: '#a1a1aa', display: 'flex', alignItems: 'center' }}>
                  +971 50 123 4567
                </Box>
                <Box sx={{ height: 28, borderRadius: 1, color: '#fff', fontSize: 11, fontWeight: 500, display: 'grid', placeItems: 'center', backgroundColor: btnColor, transition: 'background-color .2s' }}>
                  Send code
                </Box>
                <Box sx={{ fontSize: 9, textAlign: 'center', color: '#a1a1aa', lineHeight: 1.2 }}>By continuing, you agree to our Terms.</Box>
              </Box>
            </Box>
          </Box>

          {/* Properties */}
          <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
            <Input label="Headline text" value={headline} onChange={(e) => setHeadline((e.target as HTMLInputElement).value)} />
            <Box sx={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 1.5 }}>
              <ColorRow label="Background"     value={bgColor}       onChange={setBgColor} />
              <ColorRow label="Button"         value={btnColor}      onChange={setBtnColor} />
              <ColorRow label="Headline color" value={headlineColor} onChange={setHeadlineColor} />
              <ColorRow label="Logo"           value={logoBgColor}   onChange={setLogoBgColor} />
            </Box>
            <Banner tone="neutral">
              This is a focused editor for the offer's theme override. The full element-by-element editor in Step 2 still applies to the service-level theme.
            </Banner>
          </Box>
        </Box>
      </Card>

      {/* Sticky "I'm done" banner */}
      <Box sx={{
        position: 'sticky', bottom: 80, zIndex: 5,
        backgroundColor: '#fffbeb',
        border: '1px solid #fef3c7',
        borderRadius: 1.5, paddingInline: 2.5, paddingBlock: 2,
        display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 1.5,
        boxShadow: (t) => t.shadows[2], mt: 2,
      }}>
        <Box sx={{ display: 'flex', alignItems: 'flex-start', gap: 1.5, minWidth: 0 }}>
          <Box sx={{ width: 32, height: 32, borderRadius: 1, backgroundColor: '#fef3c7', color: '#b45309', display: 'grid', placeItems: 'center', flexShrink: 0 }}>
            <Paintbrush size={16} />
          </Box>
          <Box sx={{ minWidth: 0 }}>
            <Typography sx={{ fontSize: 13.5, fontWeight: 600, color: '#78350f' }}>Editing theme for {offerLabel}</Typography>
            <Typography sx={{ fontSize: 12, color: '#b45309', mt: 0.25 }}>
              Changes here only apply to this offer. Confirm when you're done.
            </Typography>
          </Box>
        </Box>
        <Button variant="primary" leftIcon={<Check size={14} />} onClick={() => setShowConfirm(true)}>
          I'm done
        </Button>
      </Box>

      <Dialog
        open={showConfirm}
        onClose={() => setShowConfirm(false)}
        title="Done editing this offer's theme?"
        description={`Your changes will be saved as a custom theme for ${offerLabel} and you'll return to the offer list.`}
        showClose={false}
      >
        <Dialog.Footer>
          <Button variant="ghost"   onClick={() => setShowConfirm(false)}>Keep editing</Button>
          <Button variant="primary" onClick={() => { setShowConfirm(false); onDone(); }}>Yes, done</Button>
        </Dialog.Footer>
      </Dialog>
    </Box>
  );
}

function ColorRow({ label, value, onChange }: { label: string; value: string; onChange: (v: string) => void }) {
  return (
    <Box>
      <Typography sx={{ fontSize: 12.5, fontWeight: 500, color: 'text.secondary', mb: 0.75 }}>{label}</Typography>
      <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
        <Box
          component="input"
          type="color"
          value={value}
          onChange={(e) => onChange((e.target as HTMLInputElement).value)}
          sx={{ width: 48, height: 36, borderRadius: 1, border: (t) => `1px solid ${t.palette.border.main}`, cursor: 'pointer', padding: 0 }}
        />
        <Typography sx={{ fontSize: 12, color: 'text.secondary', fontFamily: 'ui-monospace, SFMono-Regular, Menlo, monospace' }}>{value}</Typography>
      </Box>
    </Box>
  );
}
