/**
 * Step 5 — Review. Read-only summary of the wizard's state, grouped by step.
 *
 * Each block has an "Edit" link that jumps back to the relevant step. The
 * page passes the consolidated draft state down.
 */

'use client';

import Box from '@mui/material/Box';
import Typography from '@mui/material/Typography';
import { Pencil } from 'lucide-react';

import { Card, Chip, Button, StatusPill, Banner } from '../';
import type { Step1Values } from './Step1Service';
import type { Step2Values } from './Step2Setup';
import type { OfferDraft  } from './Step3Offers';
import type { Step4Values } from './Step4Portals';

export interface Step5ReviewProps {
  step1:  Step1Values;
  step2:  Step2Values;
  offers: OfferDraft[];
  step4:  Step4Values;
  onJumpTo: (idx: number) => void;
}

export function Step5Review({ step1, step2, offers, step4, onJumpTo }: Step5ReviewProps) {
  return (
    <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2.5 }}>
      <Box>
        <Typography component="h2" sx={{ fontSize: 16, fontWeight: 600, color: 'text.primary' }}>Review</Typography>
        <Typography sx={{ fontSize: 13, color: 'text.secondary', mt: 0.25 }}>
          Confirm the configuration before launching. You can keep editing after launch.
        </Typography>
      </Box>

      <Banner tone="info">
        After launching, this service will appear in the Services list with status <strong>Online</strong>.
      </Banner>

      <ReviewBlock title="Service" stepIndex={0} onJumpTo={onJumpTo}
        rows={[
          ['Name',     step1.name || <em>Not set</em>],
          ['Client',   step1.client || <em>Not set</em>],
          ['Category', step1.category || <em>Not set</em>],
          ['Premium',  step1.premium ? 'Yes' : 'No'],
        ]}
      />

      <ReviewBlock title="Set up" stepIndex={1} onJumpTo={onJumpTo}
        rows={[
          ['Countries', step2.countries.length > 0
            ? <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 0.5 }}>{step2.countries.map((c) => <Chip key={c} label={c} variant="soft" />)}</Box>
            : <em>None selected</em>],
          ['Default language', step2.defaultLang || <em>Not set</em>],
          ['Billing channel',  step2.channelType || <em>Not set</em>],
        ]}
      />

      <ReviewBlock title={`Offers (${offers.length})`} stepIndex={2} onJumpTo={onJumpTo}
        rows={offers.length === 0 ? [['Status', <em>No offers configured</em>]] : offers.map((o, i) => [
          `Offer-${i + 1}`,
          <Box sx={{ display: 'inline-flex', alignItems: 'center', gap: 1 }}>
            <Box component="span" sx={{ fontWeight: 500 }}>{o.name}</Box>
            <Box component="span" sx={{ color: 'text.secondary' }}>· {o.type}</Box>
            <StatusPill status={o.online ? 'online' : 'offline'} />
            {o.themed && <StatusPill status="themed" iconOnly />}
          </Box>,
        ])}
      />

      <ReviewBlock title="Portals" stepIndex={3} onJumpTo={onJumpTo}
        rows={[
          ['Country',    step4.country  || <em>Not set</em>],
          ['Operator',   step4.operator || <em>Not set</em>],
          ['Premium',    step4.premium ? 'Yes' : 'No'],
          ['Portal URL', step4.url     || <em>Not set</em>],
          ['Parameters', step4.parameters.length > 0
            ? `${step4.parameters.length} ${step4.parameters.length === 1 ? 'parameter' : 'parameters'}`
            : <em>None</em>],
        ]}
      />
    </Box>
  );
}

function ReviewBlock({ title, stepIndex, onJumpTo, rows }: {
  title: string;
  stepIndex: number;
  onJumpTo: (idx: number) => void;
  rows: Array<[string, React.ReactNode]>;
}) {
  return (
    <Card padded={false}>
      <Box sx={{
        paddingInline: 2, paddingBlock: 1.5,
        borderBottom: (t) => `1px solid ${t.palette.border.subtle}`,
        display: 'flex', alignItems: 'center', justifyContent: 'space-between',
      }}>
        <Typography component="h3" sx={{ fontSize: 14, fontWeight: 600, color: 'text.primary' }}>{title}</Typography>
        <Button variant="ghost" size="sm" leftIcon={<Pencil size={12} />} onClick={() => onJumpTo(stepIndex)}>
          Edit
        </Button>
      </Box>
      <Box component="dl" sx={{ m: 0 }}>
        {rows.map(([k, v], i) => (
          <Box key={`${k}-${i}`} sx={{
            display: 'grid', gridTemplateColumns: '160px 1fr', gap: 2,
            paddingInline: 2, paddingBlock: 1.25,
            borderTop: i === 0 ? 'none' : (t) => `1px solid ${t.palette.border.subtle}`,
          }}>
            <Box component="dt" sx={{ fontSize: 12.5, color: 'text.secondary' }}>{k}</Box>
            <Box component="dd" sx={{ m: 0, fontSize: 13, color: 'text.primary' }}>{v}</Box>
          </Box>
        ))}
      </Box>
    </Card>
  );
}
